class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;
        int[][] res = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // (i,j) 顺时针转 90 度后落在 (j, n-1-i)
                res[j][n - 1 - i] = matrix[i][j];
            }
        }

        // 题目要求原地修改，必须把 res 拷回去
        for (int i = 0; i < n; i++) {
            System.arraycopy(res[i], 0, matrix[i], 0, n);
        }
    }
}

class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;

        // 只遍历左上四分之一区域，每个格子带动四个位置一起转
        for (int i = 0; i < n / 2; i++) {
            for (int j = i; j < n - 1 - i; j++) {
                int tmp = matrix[i][j];
                matrix[i][j] = matrix[n - 1 - j][i];                  // 左下 → 左上
                matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];  // 右下 → 左下
                matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];  // 右上 → 右下
                matrix[j][n - 1 - i] = tmp;                          // 原左上 → 右上
            }
        }
    }
}

class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;

        // 第一步：沿主对角线转置。只走上三角，否则每对会被换两次
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int t = matrix[i][j];
                matrix[i][j] = matrix[j][i];
                matrix[j][i] = t;
            }
        }

        // 第二步：每一行左右翻转
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n / 2; j++) {
                int t = matrix[i][j];
                matrix[i][j] = matrix[i][n - 1 - j];
                matrix[i][n - 1 - j] = t;
            }
        }
    }
}
